package store

// This file is hand-written; the other .go files in this package are generated by sqlc.

import (
	"context"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// DB is what the API layer depends on: every generated query plus transactions.
// Handlers take this interface, not *Store, so they stay easy to test.
type DB interface {
	Querier
	// InTx runs fn in a database transaction. If fn returns an error (or panics), the
	// transaction is rolled back; otherwise it is committed. Use only the Querier passed
	// to fn inside it: queries made through anything else run outside the transaction.
	InTx(ctx context.Context, fn func(q Querier) error) error
}

// Store is the Postgres-backed DB.
type Store struct {
	*Queries
	pool *pgxpool.Pool
}

var _ DB = (*Store)(nil)

// NewStore returns a Store using pool.
func NewStore(pool *pgxpool.Pool) *Store {
	return &Store{Queries: New(pool), pool: pool}
}

// InTx implements DB.
func (s *Store) InTx(ctx context.Context, fn func(q Querier) error) error {
	// BeginFunc commits if fn returns nil and rolls back on error or panic.
	return pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		return fn(s.WithTx(tx))
	})
}
